    @NoLiveLiterals
    suspend fun fetchAccountFromFirebase(decryptedProductId: String): AccountEntity? {
        val db = getDatabase()
        val accountRef = ref(db, "products/$decryptedProductId/account")

        return try {
            val snapshot = withTimeoutOrNull(5000L) {
                get(accountRef).awaitPromise()
            } ?: return null

            if (!snapshot.exists()) return null

            val obj = snapshot.`val`()!!.asDynamic()

            AccountEntity(
                sn = (obj.sn as? Number)?.toLong() ?: 0L,
                productId = (obj.productId as? Number)?.toInt() ?: 0,
                theId = obj.theId as? String ?: "",
                decryptedProductId = obj.decryptedProductId as? String ?: "",
                accountName = obj.accountName as? String ?: "",
                companyName = obj.companyName as? String ?: "",
                sound = (obj.sound as? Number)?.toInt() ?: 0,
                primaryUuid = obj.primaryUuid as? String ?: "",
                secondaryUuid = obj.secondaryUuid as? String,
                address = obj.address as? String ?: "",
                longitude = obj.longitude as? String ?: "",
                latitude = obj.latitude as? String ?: "",
                wifiName = obj.wifiName as? String ?: "",
                wifiPass = obj.wifiPass as? String ?: "",
                autoConnect = obj.autoConnect as? Boolean ?: false,
                creationDate = obj.creationDate as? String ?: "",
                activateCount = (obj.activateCount as? Number)?.toInt() ?: 0,
                activateDate = obj.activateDate as? String ?: "",
                activatedEmployees = (obj.activatedEmployees as? Number)?.toInt() ?: 100,
                futureInt = (obj.futureInt as? Number)?.toInt() ?: 0,
                futureBool = obj.futureBool as? Boolean ?: false,
                futureFloat = (obj.futureFloat as? Number)?.toFloat() ?: 0f,
                active = obj.active as? Boolean ?: false,
                lastDate = obj.lastDate as? String ?: "",
                lastUpdated = (obj.lastUpdated as? Number)?.toLong() ?: 0L,
            )
        } catch (e: Exception) {
            if (e.message?.contains("Permission denied", ignoreCase = true) == true) {
                throw SecurityException("Permission denied for product: $decryptedProductId", e)
            }
            null
        }
    }

    @NoLiveLiterals
    fun saveAccountToSQLite(account: AccountEntity) {
        val db = dbHelper.db ?: run {
           //consol..error("IndexedDB not initialized")
            return
        }

        val tx = db.asDynamic().transaction("AccountEntity", "readwrite")
        val store = tx.objectStore("AccountEntity")

        val request = store.get(account.productId)

        request.onsuccess = { _: dynamic ->
            val existing = request.result
            if (existing != null) {
                try {
                    val weeklyScheduleList =
                        (existing.weeklySchedule as? Array<*>)?.mapNotNull { (it as? Number)?.toInt() }
                            ?: List(14) { -1 }

                    val existingAccount = AccountEntity(
                        sn = (existing.sn as? Number)?.toLong() ?: 0L,
                        productId = (existing.productId as? Number)?.toInt() ?: 0,
                        theId = existing.theId as? String ?: "",
                        decryptedProductId = existing.decryptedProductId as? String ?: "",
                        accountName = existing.accountName as? String ?: "",
                        companyName = existing.companyName as? String ?: "",
                        sound = (existing.sound as? Number)?.toInt() ?: 0,
                        primaryUuid = existing.primaryUuid as? String ?: "",
                        secondaryUuid = existing.secondaryUuid as? String ?: "",
                        address = existing.address as? String ?: "",
                        longitude = existing.longitude as? String ?: "",
                        latitude = existing.latitude as? String ?: "",
                        wifiName = existing.wifiName as? String ?: "",
                        wifiPass = existing.wifiPass as? String ?: "",
                        autoConnect = existing.autoConnect as? Boolean ?: false,
                        creationDate = existing.creationDate as? String ?: "",
                        activateCount = (existing.activateCount as? Number)?.toInt() ?: 0,
                        activateDate = existing.activateDate as? String ?: "",
                        activatedEmployees = (existing.activatedEmployees as? Number)?.toInt() ?: 100,
                        futureInt = (existing.futureInt as? Number)?.toInt() ?: 0,
                        futureBool = existing.futureBool as? Boolean ?: false,
                        futureFloat = (existing.futureFloat as? Number)?.toFloat() ?: 0f,
                        active = existing.active as? Boolean ?: false,
                        lastDate = existing.lastDate as? String ?: "",

                        // ✅ READ stays the same
                        lastUpdated = (existing.lastUpdated as? Number)?.toLong() ?: 0L,
                    )

                    if (account != existingAccount) {
                        val obj = account.toContentValues()
                        obj.lastUpdated = account.lastUpdated.toDouble()
                        store.put(obj)
                    } else {
                        Unit
                    }
                } catch (e: Exception) {
                   //consol..error("Error mapping existing AccountEntity: $e")
                    val obj = account.toContentValues()
                    obj.lastUpdated = account.lastUpdated.toDouble()
                    store.put(obj)
                }
            } else {
                // ✅ INSERT case also FIXED
                val obj = account.toContentValues()
                obj.lastUpdated = account.lastUpdated.toDouble()
                store.put(obj)
            }
        }

        request.onerror = { event: dynamic ->
           //consol..error("Error retrieving AccountEntity: ${event.target.error}")
        }

        tx.oncomplete = { _: dynamic ->
           //consol..log("AccountEntity saved successfully")
        }

        tx.onerror = { _: dynamic ->
           //consol..error("Transaction error: ${tx.error}")
        }
    }

    @NoLiveLiterals
    suspend fun syncDataFromFirebase(
        firebaseAccount: AccountEntity? = null,
    ) {
        var account = firebaseAccount
        if (account == null) {
            // Try to get decrypted productId from local state (SQLite or StateFlow)
            val localAccount = getAccountData()
            val decryptedId = localAccount?.decryptedProductId
            if (decryptedId != null) {
                account = fetchAccountFromFirebase(decryptedId)
                if (account == null) {
                    return
                }
            } else {
                return
            }
        }

        val today = js("new Date()") as Date
        val yesterday = Date(today.getTime() - 24L * 60 * 60 * 1000)
        val yesterdayStr = yesterday.toISOString().substring(0, 10) // "YYYY-MM-DD"
        val currentYear = yesterdayStr.substring(0, 4)

        var lastDate = account.lastDate
        if (lastDate.isEmpty()) {
            lastDate = account.creationDate
        }
        val lastYear = if (lastDate.isNotEmpty()) lastDate.substring(0, 4) else null
        if (lastDate < yesterdayStr) {
            val yearsToRead = if (lastYear == currentYear) {
                listOf(currentYear)
            } else {
                listOfNotNull(lastYear, currentYear)
            }
            var latestFetchedDate: String? = null

            yearsToRead.forEach { year ->
                val dailyRecords = fetchDailyRecordsFromFirebase(account.decryptedProductId, year)
                dailyRecords.values.forEach { entry ->
                    val date = entry["Date"] as String
                    val volume = (entry["Volume"] as Number).toDouble()
                    val exists = getDailyRecordByDate(date) != null
                    if (!exists) {
                        saveDailyRecord(DailyRecord(date, volume))
                    }
                    if (latestFetchedDate == null || date > latestFetchedDate!!) {
                        latestFetchedDate = date
                    }
                }
            }
            val fetched: String? = latestFetchedDate
            if (fetched != null && fetched <= yesterdayStr) {
                account.lastDate = fetched
                account.lastUpdated = today.getTime().toLong()
                saveAccountToSQLite(account)
            }
        }
       //consol..log("getting config data")
        val configData = getAdminConfigFromRTDB()
        if(configData!=null){
           //consol..log("config data: ", configData)
            saveOrUpdateOfflineAdminConfig(configData)
        }else{
           //consol..log("getting config data error")
        }
        val offlineNotifications = getOfflineNotifications(account.productId)
        val unsent = offlineNotifications.filter { !it.uploaded && it.id>=10}
        for (msg in unsent) {
            var finalMsg: AppNotification
            // Handle media uploads first if needed
            if (msg.messageType == 1 || msg.messageType == 3 || msg.messageType == 4) {
                val blob = getMedia(msg.message)
                if (blob != null) {
                    val mimeType = when (msg.messageType) {
                        1 -> "image/*"
                        3 -> "video/*"
                        4 -> "audio/*"
                        else -> "application/octet-stream"
                    }
                    val uploadOk = uploadMediaToCloud(
                        key = msg.message,
                        blob = blob,
                        mimeType = mimeType
                    )
                    if (!uploadOk) {
                        finalMsg = msg.copy(uploaded = false)
                        saveOrUpdateOfflineNotification(finalMsg)
                        addOrUpdateNotificationFromPhone(finalMsg)
                        continue
                    }
                } else {
                    finalMsg = msg.copy(uploaded = false)
                    saveOrUpdateOfflineNotification(finalMsg)
                    addOrUpdateNotificationFromPhone(finalMsg)
                    continue
                }
            }
            finalMsg = msg.copy(uploaded = true)
            // Save to RTDB
            val rtdbOk = saveMessageToRTDB(account.decryptedProductId, finalMsg)
            // Inform admin
            val unreadUserMessages = offlineNotifications.filter { it.messageSender == 1 && !it.isread }
            val count = unreadUserMessages.size
            val adminOk = informAdminOfMessage(
                productId = account.decryptedProductId,
                lastMessage = finalMsg,
                messageCount = count
            )
            // Final status
            val success = rtdbOk && adminOk
            finalMsg = finalMsg.copy(uploaded = success)
            saveOrUpdateOfflineNotification(finalMsg)
            addOrUpdateNotificationFromPhone(finalMsg)
        }
    }

    @NoLiveLiterals
    suspend fun saveAccountToFirebase(account: AccountEntity): Boolean {
        if (!NetworkStatus.isNetworkAvailable.value) return false
        // Save hardware account first
        return try {
            withTimeout(5_000L) {
                // Sanitize the account to avoid zero timestamps or serial numbers
                val sanitizedAccount = account.copy(
                    lastUpdated = if (account.lastUpdated == 0L) 1L else account.lastUpdated,
                    sn = if (account.sn == 0L) 1L else account.sn
                )

                val db = getDatabase()
                val accountRef = ref(db, "products/${account.decryptedProductId}/account")

                // Explicit mapping to plain JS object
                val obj: dynamic = js("{}")
                obj.sn = sanitizedAccount.sn.toDouble()
                obj.productId = sanitizedAccount.productId
                obj.theId = sanitizedAccount.theId
                obj.decryptedProductId = sanitizedAccount.decryptedProductId
                obj.accountName = sanitizedAccount.accountName
                obj.companyName = sanitizedAccount.companyName
                obj.sound = sanitizedAccount.sound
                obj.primaryUuid = sanitizedAccount.primaryUuid
                obj.secondaryUuid = sanitizedAccount.secondaryUuid
                obj.address = sanitizedAccount.address
                obj.longitude = sanitizedAccount.longitude
                obj.latitude = sanitizedAccount.latitude
                obj.wifiName = sanitizedAccount.wifiName
                obj.wifiPass = sanitizedAccount.wifiPass
                obj.autoConnect = sanitizedAccount.autoConnect
                obj.creationDate = sanitizedAccount.creationDate
                obj.activateCount = sanitizedAccount.activateCount
                obj.activateDate = sanitizedAccount.activateDate
                obj.activatedEmployees = sanitizedAccount.activatedEmployees
                obj.futureInt = sanitizedAccount.futureInt
                obj.futureBool = sanitizedAccount.futureBool
                obj.futureFloat = sanitizedAccount.futureFloat
                obj.active = sanitizedAccount.active
                obj.lastDate = sanitizedAccount.lastDate
                obj.lastUpdated = sanitizedAccount.lastUpdated.toDouble()
                set(accountRef, obj).awaitPromise() // modular set(ref, value)
                // Notify controller of the update
                true
            }
        } catch (_: TimeoutCancellationException) {
            false
        } catch (_: Exception) {
            false
        }
    }

