    @NoLiveLiterals
    suspend fun getOfflineNotifications(accountId: Int): List<AppNotification> {
        val db = dbHelper.db ?: return emptyList()

        return try {
            val tx = db.asDynamic().transaction("OfflineNotification", "readonly")
            val store = tx.objectStore("OfflineNotification")
            val index = store.index("accountId")

            val normalizedKey = accountId.toDouble()
            val keyRange = js("IDBKeyRange").only(normalizedKey)
            val request = index.getAll(keyRange)

            suspendCancellableCoroutine { continuation ->
                request.onsuccess = { _: dynamic ->
                    val rawResult = request.result
                    val results = (rawResult ?: emptyArray<dynamic>())
                        .unsafeCast<Array<dynamic>>()

                    val list = results.mapNotNull { obj ->
                        try {
                            AppNotification(
                                id = (obj.id as? Number)?.toInt() ?: 0,
                                accountId = (obj.accountId as? Number)?.toInt() ?: accountId,
                                title = obj.title as? String ?: "",
                                message = obj.message as? String ?: "",
                                messageType = (obj.messageType as? Number)?.toInt() ?: 0,
                                isread = when (obj.isread) {
                                    is Number -> (obj.isread as Number).toInt() == 1
                                    is Boolean -> obj.isread as Boolean
                                    else -> false
                                },
                                messageSender = (obj.messageSender as? Number)?.toInt() ?: 0,
                                timestamp = (obj.timestamp as? Number)?.toLong() ?: 0L,
                                uploaded = when (obj.uploaded) {
                                    is Number -> (obj.uploaded as Number).toInt() == 1
                                    is Boolean -> obj.uploaded as Boolean
                                    else -> false
                                },
                                shouldTranslate = when (obj.shouldTranslate) {
                                    is Number -> (obj.shouldTranslate as Number).toInt() == 1
                                    is Boolean -> obj.shouldTranslate as Boolean
                                    else -> true
                                }
                            )
                        } catch (e: Exception) {
                           //consol..error("Error parsing notification: $e")
                            null
                        }
                    }.sortedByDescending { it.timestamp }

                    if (continuation.isActive) continuation.resume(list)
                }

                request.onerror = { _: dynamic ->
                   //consol..error("Error fetching OfflineNotification for account=$accountId")
                    if (continuation.isActive) continuation.resume(emptyList())
