    @NoLiveLiterals
    suspend fun markIncomingMessages(
        account: AccountEntity,
        markRead: Boolean,
        isAdmin:Boolean = false,
        notifications: List<AppNotification>
    ) {
        var didUpdateSomething = false
        val targets = notifications.filter { msg ->
            if (msg.id < 10) return@filter false
            // 🔑 sender/role matching
            val isRelevant = (isAdmin && msg.messageSender != 0) ||
                    (!isAdmin && msg.messageSender == 0)
            if (!isRelevant) return@filter false

            // 🔍 determine if update is actually needed
            val needsUpdate =
                if (markRead) {
                    !msg.isread || !msg.shouldTranslate
                } else {
                    !msg.shouldTranslate
                }
            needsUpdate
        }
        if (targets.isEmpty()) {
            return
        }
        targets.forEach { msg ->
            val updated =
                if (markRead) {
                    msg.copy(
                        isread = true,
                        shouldTranslate = true
                    )
                } else {
                    msg.copy(
                        shouldTranslate = true
                    )
                }
            // 🔥 FINAL SAFETY CHECK: skip if no actual change
            if (updated == msg) return@forEach
            didUpdateSomething = true
            if (!isAdmin) {
                addOrUpdateNotificationFromPhone(updated)
                saveOrUpdateOfflineNotification(updated)
            }
            saveMessageToRTDB(
                account.decryptedProductId,
                updated
            )
        }
        // ❌ If nothing actually changed, stop here
        if (!didUpdateSomething) {
            println("No real state changes applied")
            return
        }
        if (!isAdmin) {
            val refreshed = getOfflineNotifications(account.productId)
            val unreadUserMessages = refreshed.filter {
                it.messageSender == 1 && !it.isread
            }
            val unreadCount = unreadUserMessages.size
            val virtualNotification = AppNotification(
                id = -1,
                accountId = account.productId,
                title = "StatusUpdate",
                message = "",
                messageType = 0,
                isread = true,
                messageSender = 0,
                timestamp = Clock.System.now().toEpochMilliseconds(),
                uploaded = true,
                shouldTranslate = true
            )
            val adminUpdated = informAdminOfMessage(
                productId = account.decryptedProductId,
                lastMessage = virtualNotification,
                messageCount = unreadCount
            )
            println("ADMIN UPDATE RESULT = $adminUpdated")
        }
    }

