            obj.volume = record.volume

            val request = store.put(obj) // keyPath = date, so no explicit key needed

            request.onsuccess = { _: dynamic ->
               //consol..log("DailyRecord saved: $obj")
                if (cont.isActive) cont.resume(Unit)
            }
            request.onerror = { _: dynamic ->
               //consol..error("Error saving DailyRecord: $obj")
                if (cont.isActive) cont.resume(Unit)
            }
        }
    }

    @NoLiveLiterals
    suspend fun getDailyRecords(interval: String): List<DailyRecord> {
        val db = dbHelper.db ?: return emptyList()
        val tx = db.asDynamic().transaction("DailyRecords", "readonly")
        val store = tx.objectStore("DailyRecords")
        val request = store.getAll()

        return suspendCancellableCoroutine { cont ->
            request.onsuccess = { _: dynamic ->
                val results = (request.result ?: emptyArray<dynamic>())
                    .unsafeCast<Array<dynamic>>()
                    .map {
                        DailyRecord(
                            date = it.date as String,
                            volume = (it.volume as? Number)?.toDouble() ?: 0.0
                        )
                    }

                // Compute cutoff using JS Date
                val now = js("new Date()") as Date
                val cutoff: Date? = when (interval) {
                    "1M" -> Date(now.getTime() - 30L * 24 * 60 * 60 * 1000) // ~30 days
                    "3M" -> Date(now.getTime() - 90L * 24 * 60 * 60 * 1000) // ~90 days
                    "6M" -> Date(now.getTime() - 180L * 24 * 60 * 60 * 1000) // ~180 days
                    "1Y" -> Date(now.getTime() - 365L * 24 * 60 * 60 * 1000) // ~365 days
                    "ALL" -> null
                    else -> null
                }
                val filtered = if (cutoff != null) {
                    results.filter {
                        val recordDate = Date(it.date) // parse "YYYY-MM-DD"
                        recordDate.getTime() >= cutoff.getTime()
                    }
                } else results

                cont.resume(filtered)
            }

            request.onerror = { _: dynamic ->
               //consol..error("Error fetching DailyRecords")
                cont.resume(emptyList())
            }
        }
    }

    @NoLiveLiterals
    suspend fun getDailyRecordByDate(date: String): DailyRecord? {
        val db = dbHelper.db ?: return null
        val tx = db.asDynamic().transaction("DailyRecords", "readonly")
        val store = tx.objectStore("DailyRecords")
        val request = store.get(date)

        return suspendCancellableCoroutine { cont ->
            request.onsuccess = { _: dynamic ->
                val result = request.result
                if (result != null) {
                    cont.resume(
                        DailyRecord(
                            date = result.date as String,
                            volume = (result.volume as? Number)?.toDouble() ?: 0.0
                        )
                    )
                } else {
                    cont.resume(null)
                }
            }
            request.onerror = { _: dynamic ->
               //consol..error("Error fetching DailyRecord for $date")
                cont.resume(null)
            }
        }
    }

    @NoLiveLiterals
    suspend fun fetchDailyRecordsFromFirebase(
        decryptedProductId: String,
        year: String
    ): Map<String, dynamic> {
        val db = getDatabase()
        val recordsRef = ref(db, "products/$decryptedProductId/DailyRecords/$year")

        return try {
            val snapshot = withTimeoutOrNull(5000L) {
                get(recordsRef).awaitPromise()
            } ?: return emptyMap()

            if (!snapshot.exists()) {
               //consol..log("No snapshot exists at path products/$decryptedProductId/DailyRecords/$year")
                return emptyMap()
            }

            val raw = snapshot.`val`() ?: return emptyMap()
            val jsObj = raw.unsafeCast<dynamic>()
            val keys = js("Object.keys(jsObj)") as Array<String>

            val result = mutableMapOf<String, dynamic>()
            for (key in keys) {
                result[key] = jsObj[key]
               //consol..log("Fetched record key=$key, value=${JSON.stringify(jsObj[key])}")
            }

           //consol..log("Total records fetched for year $year: ${result.size}")
            result
        } catch (e: Exception) {
           //consol..error("Error fetching DailyRecords for product=$decryptedProductId, year=$year", e)
            if (e.message?.contains("Permission denied", ignoreCase = true) == true) {
                throw SecurityException("Permission denied for product: $decryptedProductId", e)
            }
            emptyMap()
        }
    }

    @NoLiveLiterals
    suspend fun saveOrUpdateOfflineAdminConfig(
        config: AdminConfig
    ) {
        val db = dbHelper.db ?: return
        val tx = db.asDynamic().transaction("OfflineAdminConfig", "readwrite")
        val store = tx.objectStore("OfflineAdminConfig")

        suspendCancellableCoroutine<Unit> { cont ->
            val obj = js("{}")

            obj.singleton = "singleton" // ✅ inline keyPath
            obj.initialInvestment   = config.initialInvestment
            obj.bottledWaterCost    = config.bottledWaterCost
            obj.preFilterCapacity   = config.preFilterCapacity
            obj.preFilterCost       = config.preFilterCost
            obj.roMembraneCapacity  = config.roMembraneCapacity
            obj.roMembraneCost      = config.roMembraneCost
            obj.postCarbonCapacity  = config.postCarbonCapacity
            obj.postCarbonCost      = config.postCarbonCost
            obj.bottleSize          = config.bottleSize
            obj.bottleWeight        = config.bottleWeight

            val request = store.put(obj)

            request.onsuccess = { _: dynamic ->
               //consol..log("AdminConfig saved/updated successfully")
            }
            request.onerror = { _: dynamic ->
               //consol..error("Error saving AdminConfig")
                if (cont.isActive) cont.resume(Unit)
            }
            tx.oncomplete = { _: dynamic ->
                if (cont.isActive) cont.resume(Unit)
            }
            tx.onerror = { _: dynamic ->
                if (cont.isActive) cont.resume(Unit)
            }
        }
    }

    @NoLiveLiterals
    suspend fun getOfflineAdminConfig(): AdminConfig? {
        val db = dbHelper.db ?: return null

        return try {
            val tx = db.asDynamic().transaction("OfflineAdminConfig", "readonly")
            val store = tx.objectStore("OfflineAdminConfig")
            val request = store.get("singleton")

            suspendCancellableCoroutine { continuation ->
                request.onsuccess = { _: dynamic ->
                    val obj = request.result
                    if (obj != null) {
                        try {
                            val config = AdminConfig(
                                initialInvestment   = (obj.initialInvestment   as? Number)?.toDouble() ?: 0.0,
                                bottledWaterCost    = (obj.bottledWaterCost    as? Number)?.toDouble() ?: 0.0,
                                preFilterCapacity   = (obj.preFilterCapacity   as? Number)?.toDouble() ?: 0.0,
                                preFilterCost       = (obj.preFilterCost       as? Number)?.toDouble() ?: 0.0,
                                roMembraneCapacity  = (obj.roMembraneCapacity  as? Number)?.toDouble() ?: 0.0,
                                roMembraneCost      = (obj.roMembraneCost      as? Number)?.toDouble() ?: 0.0,
                                postCarbonCapacity  = (obj.postCarbonCapacity  as? Number)?.toDouble() ?: 0.0,
                                postCarbonCost      = (obj.postCarbonCost      as? Number)?.toDouble() ?: 0.0,
                                bottleSize          = (obj.bottleSize          as? Number)?.toDouble() ?: 0.0,
                                bottleWeight        = (obj.bottleWeight        as? Number)?.toDouble() ?: 0.0
                            )
                           //consol..log("Fetched AdminConfig from IndexedDB: $config")
                            if (continuation.isActive) continuation.resume(config)
                        } catch (e: Exception) {
                           //consol..error("Error parsing AdminConfig: $e")
                            if (continuation.isActive) continuation.resume(null)
                        }
                    } else {
                       //consol..log("No AdminConfig found in IndexedDB")
                        if (continuation.isActive) continuation.resume(null)
                    }
                }
                request.onerror = { _: dynamic ->
                   //consol..error("Error fetching OfflineAdminConfig from IndexedDB")
                    if (continuation.isActive) continuation.resume(null)
                }
            }
        } catch (e: Exception) {
           //consol..error("Exception in getOfflineAdminConfig: $e")
            null
        }
    }

