package com.e_water_gate.app

import kotlin.math.max

object FusionLogic {

    private const val TURBIDITY_WEIGHT = 0.4f
    private const val TDS_WEIGHT = 0.4f
    private const val PH_WEIGHT = 0.19f
    private const val TEMP_WEIGHT = 0.01f
    private const val ROOM_TEMPERATURE = 25f

    private fun mapValue(
        value: Float,
        fromLow: Float,
        fromHigh: Float,
        toLow: Float,
        toHigh: Float
    ): Float {
        return (value - fromLow) *
                (toHigh - toLow) /
                (fromHigh - fromLow) + toLow
    }

    private data class ZoneResult(val zone: Int, val percentage: Float)

    private fun clampToPlateau(p: Float): Float {
        // 🔑 plateau: treat anything >=95 as 100
        return if (p >= 95f) 100f else p
    }

    private fun getZone(
        value: Float,
        criticalMin: Float,
        criticalMax: Float,
        warningMin: Float,
        warningMax: Float,
        idealMin: Float,
        idealMax: Float,
        isTemp: Boolean = false
    ): ZoneResult {
        val scaled = value * 10
        val cMin = criticalMin * 10
        val cMax = criticalMax * 10
        val wMin = warningMin * 10
        val wMax = warningMax * 10
        val iMin = idealMin * 10
        val iMax = idealMax * 10

        if (scaled in iMin..iMax) {
            val percentage = if (isTemp) {
                var p = mapValue(scaled, 0f, ROOM_TEMPERATURE * 2 * 10, 0f, 200f)
                if (p > 100f) p = 200f - p
                clampToPlateau(p)
            } else {
                clampToPlateau(mapValue(scaled, iMin, iMax, 100f, 0f))
            }
            return ZoneResult(1, percentage)
        }

        if (scaled in wMin..wMax) {
            return ZoneResult(2, mapValue(scaled, wMin, wMax, 100f, 0f))
        }

        if (scaled in cMin..cMax) {
            return ZoneResult(3, mapValue(scaled, cMin, cMax, 100f, 0f))
        }

        return ZoneResult(3, 0f)
    }

    private fun getPHZone(ph: Float): ZoneResult {
        return when {
            ph in 6.5f..7.5f -> {
                var percentage = mapValue(ph * 10, 65f, 75f, 0f, 200f)
                if (percentage > 100f) percentage = 200f - percentage
                ZoneResult(1, clampToPlateau(percentage))
            }
            ph in 6.0f..6.5f -> ZoneResult(2, mapValue(ph * 10, 60f, 65f, 0f, 100f))
            ph in 7.5f..8.5f -> ZoneResult(2, mapValue(ph * 10, 75f, 85f, 100f, 0f))
            ph in 0f..6.0f -> ZoneResult(3, mapValue(ph * 10, 0f, 60f, 0f, 100f))
            else -> ZoneResult(3, mapValue(ph * 10, 85f, 140f, 100f, 0f))
        }
    }

    /** Single entry point: feed in sensor values + lifespan, get back a percentage */
    fun calculatePercentage(
        turbidity: Float,
        tds: Float,
        ph: Float,
        temperature: Float,
        lifespan: Float
    ): Float {
        val turbidityResult = getZone(turbidity, 5f, 100f, 1f, 5f, 0f, 1f)
        val tdsResult = getZone(tds, 300f, 1000f, 50f, 300f, 0f, 50f)
        val phResult = getPHZone(ph)
        val tempResult = getZone(temperature, 40f, 100f, 30f, 40f, 10f, 30f, true)

        val finalZone = max(max(turbidityResult.zone, tdsResult.zone), max(phResult.zone, tempResult.zone))

        val weightedTotal =
            (turbidityResult.percentage * TURBIDITY_WEIGHT) +
                    (tdsResult.percentage * TDS_WEIGHT) +
                    (phResult.percentage * PH_WEIGHT) +
                    (tempResult.percentage * TEMP_WEIGHT)

        return when {
            lifespan > 200 -> 0f
            lifespan > 100 -> weightedTotal * 0.5f
            finalZone == 1 -> mapValue(weightedTotal, 0f, 100f, 91f, 100f) // 🔑 plateau range
            finalZone == 2 -> mapValue(weightedTotal, 0f, 100f, 51f, 90f)
            else -> mapValue(weightedTotal, 0f, 100f, 0f, 50f)
        }
    }
}
