package com.e_water_gate.app

data class UserEntity(
    val uuid: String = "",
    val name: String = "",
    val email: String = "",
    val ownedProducts: List<String> = listOf(),
    val isLoggedIn: Boolean = false,
    val loggedIntoProduct: String = "",
    val lastAccessedDate: String = "",
    val lastLoginRole: String = "",
    val creationDate: String = "",
    val language: String = "English"
)

data class SignInResult(
    val user: firebase.auth.User? = null,
    val error: String? = null
)

data class AccountEntity(
    var sn: Long = 0L,
    var productId: Int = 0,
    var theId: String = "",
    var decryptedProductId: String = "",
    var accountName: String = "",
    var companyName: String = "",
    var sound: Int = 0,
    var primaryUuid: String = "",
    var secondaryUuid: String? = null,
    var address: String = "",
    var longitude: String = "",
    var latitude: String = "",
    var wifiName: String = "",
    var wifiPass: String = "",
    var autoConnect: Boolean = false,
    var creationDate: String = "",
    var activateCount: Int = 0,
    var activateDate: String = "",
    var activatedEmployees: Int = 100,
    var futureInt: Int = 0,
    var futureBool: Boolean = false,
    var futureFloat: Float = 0f,
    var active: Boolean = false,
    var lastDate: String = "",
    var lastUpdated: Long = 0L
)

data class AppNotification(
    val id: Int = 0,
    val accountId: Int = 0,
    val title: String = "",
    val message: String = "",
    val messageType:Int = 0,
    val isread:Boolean = false,
    val messageSender:Int = 0,
    val timestamp: Long = 0,
    var uploaded: Boolean = false,
    val shouldTranslate: Boolean = true
)

data class AdminNotification(
    val productId: String,   // decrypted productId
    val lastMessageTime: Long, // epoch millis or seconds
    val messageCount: Int,   // number of new messages
    val lastMessageId: Int   // id of the latest message
)

data class WaterResult(
    // --- SensorValue ---
    val turbidity: Float = 0f,
    val ph: Float = 0f,
    val tds: Float = 0f,
    val temperature: Float = 0f,
    val volume: Float = 0f,
    val time: Long = 0L,

    // --- General ---
    val mineralDate: String = "",
    val mineralVolume: Float = 0f,
    val mineralCount: Int = 0,
    val preDate: String = "",
    val preVolume: Float = 0f,
    val preCount: Int = 0,
    val reverseDate: String = "",
    val reverseVolume: Float = 0f,
    val reverseCount: Int = 0,
    val totalVolume: Float = 0f,

    // --- Status ---
    val filter: String = "",
    val sensor: String = ""
)

data class DailyRecord(
    val date: String,
    val volume: Double
)

data class AdminConfig(
    val initialInvestment: Double = 200000.0,   // I (FCFA) ~ cost of a household RO unit
    val bottledWaterCost: Double = 250.0,       // C (FCFA per liter, ~225 FCFA for 1.5L bottle)
    val preFilterCapacity: Double = 34000.0,    // K1 (liters, from doc)
    val preFilterCost: Double = 5000.0,         // C1 (FCFA per cartridge)
    val roMembraneCapacity: Double = 138000.0,  // K2 (liters, from doc)
    val roMembraneCost: Double = 25000.0,       // C2 (FCFA per membrane)
    val postCarbonCapacity: Double = 68000.0,   // K3 (liters, from doc)
    val postCarbonCost: Double = 8000.0,        // C3 (FCFA per cartridge)
    val bottleSize: Double = 1.5,               // B (liters per PET bottle)
    val bottleWeight: Double = 30.0             // W (grams per 1.5L PET bottle)
)
