        val db = getDatabase()

        console.log("📥 Loading users...")
        val usersRef = ref(db, "users")
        val usersSnap = get(usersRef).await()

        if (usersSnap.exists()) {
            val obj = usersSnap.`val`() ?: run {
                console.error("❌ Users snapshot value is null")
                setAdminLoading(false)
                return
