suspend fun enterApp(
    account: AccountEntity,
    repository: FirebaseAndIndexedDBRepository
) {
    try {
        val user = repository.getUserFromSQLite()
        if (user == null) {
            console.error("User not found in SQLite")
            AppState.setScreen(Screen.Login)
            return
        }
        updateUser(user)
        updateAccountData(account)
        repository.saveAccountToSQLite(account)
        AppState.setScreen(Screen.Main(account))
        loadPostLoginData(
            account = account,
            repository = repository,
            onOfflineErrors = { setOfflineErrors(it) },
            onOfflineResult = { setWaterResult(it) }
        )
        setupPersistence(repository, waterResult)
    } catch (e: Exception) {
        console.error("EnterApp failed", e)
    }
}

suspend fun loadPostLoginData(
    account: AccountEntity,
    repository: FirebaseAndIndexedDBRepository,
    onOfflineErrors: (List<AppNotification>) -> Unit,
    onOfflineResult: (WaterResult) -> Unit
) {
    try {
        monitorSNForUpdates(repository, account.decryptedProductId)
        loadNotifications(account, repository)
        loadAdminConfig(account, repository)
        loadWaterResults(account, repository)
        val local = repository.getOfflineNotifications(account.productId)
        val storeResult = repository.getOfflineWaterResult()
        val current = offlineErrors.value ?: emptyList()
        val merged = (current + local)
            .sortedByDescending { it.timestamp }
            .distinctBy { it.id }
        onOfflineErrors(merged)
        if (storeResult != null) {
            onOfflineResult(storeResult)
        }
    } catch (_: Exception) {
        // optionally log
    }
}

@NoLiveLiterals
suspend fun initializeAppAndLogin(
    repository: FirebaseAndIndexedDBRepository,
    updateUser: (UserEntity) -> Unit,
    updateAccountData: (AccountEntity) -> Unit,
    updateOfflineErrors: (List<AppNotification>) -> Unit,
    currentOfflineErrors: List<AppNotification> = emptyList()
): Boolean {
    return try {
        val user = repository.getUserFromSQLite() ?: return false
        if (!user.isLoggedIn || user.loggedIntoProduct.isBlank()) return false
        // 🔑 Admin branch
        if (user.loggedIntoProduct == "admin" && user.lastLoginRole == "admin") {
            val adminUser = user.copy(
                isLoggedIn = true,
                loggedIntoProduct = "admin",
                lastLoginRole = "admin",
                lastAccessedDate = getCurrentDateFormatted()
            )
            repository.saveUserToSQLite(adminUser)
            repository.saveUserToRTDB(adminUser)
            updateUser(adminUser)
            // Admin doesn’t need AccountEntity
            val mergedErrors = currentOfflineErrors
                .sortedByDescending { it.timestamp }
                .distinctBy { it.id }
            updateOfflineErrors(mergedErrors)

            return true
        }

        // 🔑 Normal user branch
        val allAccounts = repository.getAccountsFromSQLite()
        var account = allAccounts.find { it.decryptedProductId == user.loggedIntoProduct }
        var updatedUser = user

        if (account == null) {
            for (ownedProductId in user.ownedProducts) {
                val matchedAccount = allAccounts.find { it.decryptedProductId == ownedProductId }
                if (matchedAccount != null) {
                    val newUpdatedUser = user.copy(
                        loggedIntoProduct = matchedAccount.decryptedProductId,
                        lastLoginRole = "user",
                        lastAccessedDate = getCurrentDateFormatted(),
                        isLoggedIn = true
                    )
                    repository.saveUserToSQLite(newUpdatedUser)
                    account = matchedAccount
                    updatedUser = newUpdatedUser
                    break
                }
            }
            if (account == null) return false
        }

        updateUser(updatedUser)
        updateAccountData(account)

        val mergedErrors = currentOfflineErrors
            .sortedByDescending { it.timestamp }
            .distinctBy { it.id }
        updateOfflineErrors(mergedErrors)

        true
    } catch (e: Exception) {
        e.printStackTrace()
        false
    }
}

fun getCurrentTimeInAccountSeconds(): Long {
    val nowUtc: Instant = Clock.System.now()
    val accountInstant = nowUtc
    return accountInstant.epochSeconds
}


