@Composable
fun AdminMainContent(
    accountUser: UserEntity,
    currentPage: String,
    repository: FirebaseAndIndexedDBRepository,
    onPageChange: (String) -> Unit,
    isMobile:Boolean
) {

    var selectedProductId by remember { mutableStateOf<String?>(null) }
    val usersByProduct by adminUsersByProduct.collectAsState()
    val devicesByProduct by adminDevicesByProduct.collectAsState()
    val accountsByProduct by adminAccountsByProduct.collectAsState()
    val waterByProduct by adminWaterResultsByProduct.collectAsState()
    val notificationsByProduct by adminNotificationsByProduct.collectAsState()
    val summariesByProduct by adminNotificationSummaryByProduct.collectAsState()
    val loading by adminIsLoading.collectAsState()
    var countdown by remember { mutableStateOf(5) }
    var loadingMessage by remember { mutableStateOf("Loading all product info…") }

    LaunchedEffect(loading) {
        if (loading) {
            countdown = 5
            while (countdown > 0 && loading) {
                loadingMessage = when (countdown) {
                    5 -> "(1/5) Preparing data, please wait…"
                    4 -> "(2/5) Fetching users…"
                    3 -> "(3/5) Fetching devices…"
                    2 -> "(4/5) Fetching products…"
                    1 -> "(5/5) Fetching water results…"
                    else -> "Almost done…"
                }
                delay(1000)
                countdown--
            }
        }
    }

    if (loading) {
        Div({
            style {
                property("width", "100%")
                property("height", "100%")
                property("display", "flex")
                property("justify-content", "center")
                property("align-items", "center")
                property("font-size", "18px")
                property("color", "#164C83")
                property("font-weight", "600")
            }
        }) {
            Text(loadingMessage)
        }
        return
    }

    Div({
        style {
            flexGrow(1)
            display(DisplayStyle.Flex)
            flexDirection(FlexDirection.Column)
            backgroundColor(Color("white"))
            height(100.percent)
            property("overflow", "hidden")
            boxSizing("border-box")
        }
    }) {
        // ================= BODY =================
        Div({
            style {
                flexGrow(1)
                property("min-height", "0")
                overflowY("auto")
                boxSizing("border-box")
            }
        }) {
            when (currentPage.lowercase()) {
                "home" -> {
                    AdminHome(
                        usersByProduct = usersByProduct,
                        devicesByProduct = devicesByProduct,
                        accountsByProduct = accountsByProduct,
                        waterByProduct = waterByProduct,
                        notificationsByProduct = notificationsByProduct,
                        summariesByProduct = summariesByProduct,
                        loading = loading,
                        isMobile = isMobile
                    )
                }

                "products" -> {
                    AdminProductsPage(
                        accountsByProduct = accountsByProduct,
                        waterByProduct = waterByProduct,
                        usersByProduct = usersByProduct,
                        notificationsByProduct = notificationsByProduct,
                        devicesByProduct = devicesByProduct,
                        summariesByProduct = summariesByProduct,
                        loading = loading,
                        onProductClick = { productId ->
                            selectedProductId = productId
                            onPageChange("charts")
                        },
                        onOpenMap = {

                          },
                    )
                }

                "settings" -> {
                    AdminSettingsPage(
                        user = accountUser,
                        onCancel = {
                            onPageChange("home")
                        },
                        onSave = { newConfig, accountUser ->
                            onPageChange("home")
                        },
                        repository = repository
                    )
                }
                "charts" -> {
                    selectedProductId?.let { pid ->
                        AdminChartsPage(
                            repository = repository,
                            productId = pid,
                            accountHere = accountsByProduct[pid]!!,
                            rawMessages = notificationsByProduct[pid] ?: emptyList(),
                            summary = summariesByProduct[pid]
                        )
                    } ?: Text("No product selected")
                }
                else -> {
                    Text("Page not found: $currentPage")
                }
            }
        }
    }
}


