@Composable
fun AdminHome(
    usersByProduct: Map<String, UserEntity>,
    devicesByProduct: Map<String, Map<String, Boolean>>,
    accountsByProduct: Map<String, AccountEntity>,
    waterByProduct: Map<String, WaterResult>,
    notificationsByProduct: Map<String, List<AppNotification>>,
    summariesByProduct: Map<String, AdminNotification>,
    loading: Boolean,
    isMobile:Boolean
) {

    if (loading) {
        Div({
            style {
                property("width", "100%")
                property("height", "100%")
                property("display", "flex")
                property("justify-content", "center")
                property("align-items", "center")
            }
        }) {
            Text("Loading...")
        }
        return
    }
    val totalProducts = accountsByProduct.size
    val totalFilteredToday =
        waterByProduct.values.sumOf { it.volume.toDouble() }
    val totalFilteredSincePurchase =
        waterByProduct.values.sumOf { (it.totalVolume + it.volume).toDouble() }
    val now = Clock.System.now().toEpochMilliseconds()
    val fiveMinutesAgo = now - (5 * 60 * 1000)
    val totalOnline =
        waterByProduct.values.count { it.time * 1000 >= fiveMinutesAgo }
    val totalSensorErrors =
        waterByProduct.values.count { it.sensor.isNotBlank() }
    val preDue = waterByProduct.values.count { it.filter.contains("Pre") }
    val reverseDue = waterByProduct.values.count { it.filter.contains("Reverse") }
    val mineralDue = waterByProduct.values.count { it.filter.contains("Mineral") }
    val totalUnreadMessages =
        accountsByProduct.keys.sumOf { productId ->
            val notifications = notificationsByProduct[productId] ?: emptyList()
            notifications.count { !it.isread && it.messageSender == 1 && it.id >= 10 }
        }

    val totalAttention =
        accountsByProduct.keys.count { productId ->
            val water = waterByProduct[productId]
            val notifications = notificationsByProduct[productId] ?: emptyList()
            val device = devicesByProduct[productId]

            val unread = notifications.any { !it.isread && it.messageSender == 1 }
            val sensorIssue = water?.sensor?.isNotBlank() == true
            val filterIssue = water?.filter?.isNotBlank() == true
            val deviceIssue = device?.get("authenticated") == false

            unread || sensorIssue || filterIssue || deviceIssue
        }

    Div({
        style {
            property("width", "100%")
            property("max-height", "700px")
            property("display", "flex")
            property("flex-direction", "column")
            property("gap", "32px")
            paddingLeft(if(isMobile) 1.px else 24.px)
            paddingRight(if(isMobile) 1.px else 24.px)
            property("box-sizing", "border-box")
            property("overflow-y", "auto")
        }
    }) {

        MetricSection("SYSTEM OVERVIEW") {
            AdminMetricCard("Products", totalProducts.toString(), "filter")
            AdminMetricCard("Online", totalOnline.toString(), "wifi")
            AdminMetricCard("Attention", totalAttention.toString(), "attention", totalAttention > 0)
        }

        MetricSection("WATER PERFORMANCE") {
            AdminMetricCard("Filtered Today", "${totalFilteredToday} L", "today")
            AdminMetricCard("Filtered Total", "${totalFilteredSincePurchase} L", "total")
        }

        MetricSection("FILTER MAINTENANCE NEEDS") {
            AdminMetricCard("Pre Filter", preDue.toString(), "pre", preDue > 0)
            AdminMetricCard("RO Filter", reverseDue.toString(), "reverse", reverseDue > 0)
            AdminMetricCard("Mineralisation", mineralDue.toString(), "mine", mineralDue > 0)
        }

        MetricSection("SENSOR MAINTENANCE NEEDS") {
            AdminMetricCard("Sensor Errors", totalSensorErrors.toString(), "sensor_error", totalSensorErrors > 0)
            AdminMetricCard("New Messages", totalUnreadMessages.toString(), "notification", totalUnreadMessages > 0)
        }
    }
}

