@Composable
fun MainContent(
    currentPage: String,
    repository: FirebaseAndIndexedDBRepository,
    onPageChange: (String) -> Unit,
    isMobile: Boolean
) {
    val accountHere by accountState.collectAsState()
    val accountUser by userState.collectAsState()
    val liveWaterResult by waterResult.collectAsState()
    val adminConfig by produceState(initialValue = AdminConfig()) {
        value = repository.getOfflineAdminConfig() ?: AdminConfig()
    }

    // ================= FILTER CHECK =================
    val percent = liveWaterResult.let { raw ->
        val filters = raw.filter.split(",").map { it.trim() }

        val needsPre = filters.contains("Pre")
        val needsReverse = filters.contains("Reverse")
        val needsMineral = filters.contains("Mineral")

        // Decide lifespan based on filter status
        val lifespan = when {
            needsPre && needsReverse && needsMineral -> 299f
            needsPre || needsReverse || needsMineral -> 199f
            else -> 99f
        }

        FusionLogic.calculatePercentage(
            turbidity = raw.turbidity,
            tds = raw.tds,
            ph = raw.ph,
            temperature = raw.temperature,
            lifespan = lifespan
        )
    } ?: 0f

    val scope = rememberCoroutineScope()
    val safeAccount = accountHere ?: return
    val safeUser = accountUser ?: return

    fun pageTitle(): String {
        return when (currentPage.lowercase()) {
            "home" -> "WATER HEALTH"
            "model" -> "SYSTEM 3D MODEL"
            "quality" -> "WATER QUALITY PARAMETERS"
            "gains" -> "GAINS"
            "chats" -> "CHAT"
            "settings" -> "SETTINGS"
            "notifications" -> "NOTIFICATIONS"
            else -> currentPage.uppercase()
        }
    }

    @Composable
    fun PageBody() {
        when (currentPage.lowercase()) {
            "home" -> HomePage(liveWaterResult, percent)
            "model" -> ModelPage()
            "quality" ->  QualityPage(liveWaterResult, percent)
            "gains" -> GainsPage(
                liveWaterResult, repository,
                config = adminConfig
            )
            "chats" -> ChartsPage(repository)
            "settings" -> SettingsPage(
                account = safeAccount,
                accountUser = safeUser,
                onCancel = {
                    onPageChange("home")
                },
                onSave = { newAccount, updatedUser ->
                    updateAccountData(newAccount)
                    scope.launch {
                        repository.saveAccountToSQLite(newAccount)
                        repository.saveAccountToFirebase(newAccount)
                        repository.saveUserToRTDB(updatedUser)
                        repository.saveUserToSQLite(updatedUser)
                    }
                    onPageChange("home")
                }
            )
            "notifications" -> NotificationsPage(
                account = safeAccount,
                onClose = {
                    onPageChange("home")
                }
            )
            else -> Text("Page not found: $currentPage")
        }
    }
    Div({
        style {
            flexGrow(1)
            display(DisplayStyle.Flex)
            flexDirection(FlexDirection.Column)
            backgroundColor(Color("white"))
            height(100.percent)
            property("overflow", "hidden")
            boxSizing("border-box")
        }
    }) {

        // ================= HEADER =================
        Div({
            style {
                width(100.percent)
                height(30.px)
                display(DisplayStyle.Flex)
                justifyContent(JustifyContent.Center)
                alignItems(AlignItems.Center)
                fontSize(18.px)
                fontWeight("bold")
                backgroundColor(Color("#FFFFFF"))
            }
        }) {
            Text(pageTitle())
        }
        // ================= BODY =================
