@Composable
fun QualityBar(value: Float) {
    // clamp percentage
    val percentage = value.coerceIn(0f, 100f)

    // compute relative position
    val leftPercent = when {
        percentage <= 50f -> {
            // map 0–50 → 0–33.33
            (percentage / 50f) * 33.33f
        }
        percentage <= 75f -> {
            // map 50–75 → 33.33–66.66
            33.33f + ((percentage - 50f) / 25f) * 33.33f
        }
        else -> {
            // map 75–100 → 66.66–100
            66.66f + ((percentage - 75f) / 25f) * 33.33f
        }
    }

    Div({
        style {
            width(90.percent)
            maxWidth(700.px)
            display(DisplayStyle.Flex)
            flexDirection(FlexDirection.Column)
        }
    }) {
        Div({
            style {
