@Composable
fun QualityPage(result: WaterResult, percent: Float) {
    // --- Define ideal baselines ---
    val baselineCa = 30f
    val baselineMg = 10f
    val baselineNa = 20f
    val baselineK = 5f

    // --- Deviations from ideal conditions ---
    val turbidityDeviation = result.turbidity * 0.5f   // more turbidity → more Na
    val phDeviationCa = (result.ph - 7f) * 2f          // away from neutral → Ca shifts
    val phDeviationNa = (result.ph - 7f) * 1.5f        // away from neutral → Na shifts
    val tempDeviationMg = (result.temperature - 20f) * 0.3f // warmer → Mg shifts
    val tempDeviationK = (result.temperature - 20f) * 0.2f  // warmer → K shifts
    val tdsDeviationCa = result.tds * 0.02f
    val tdsDeviationMg = result.tds * 0.015f
    val tdsDeviationK = result.tds * 0.01f

    // --- Final values with coerce ranges ---
    val calcium = (baselineCa + phDeviationCa + tdsDeviationCa + percent * 0.1f).coerceIn(10f, 40f)
    val magnesium = (baselineMg + tempDeviationMg + tdsDeviationMg + percent * 0.05f).coerceIn(5f, 25f)
    val sodium = (baselineNa + turbidityDeviation + phDeviationNa + percent * 0.2f).coerceIn(5f, 50f)
    val potassium = (baselineK + tempDeviationK + tdsDeviationK + percent * 0.05f).coerceIn(2f, 10f)

    Div({
        style {
            display(DisplayStyle.Flex)
            flexDirection(FlexDirection.Column)
            alignItems(AlignItems.Center)
            width(100.percent)
        }
    }) {
        LiveDataStream(result)
        MineralhomeWeb(
            calcium = (calcium.asDynamic().toFixed(1) as String),
