suspend fun calculateGains(
    repository: FirebaseAndIndexedDBRepository,
    interval: String,
    config: AdminConfig,
    todayVolume: Float
): GainsData {
    // Pull actual daily records for the interval
    val records = repository.getDailyRecords(interval)
    // Sum the volumes
    val totalVolume = records.sumOf { it.volume } + todayVolume
    // Financial savings
    val savings = totalVolume * config.bottledWaterCost -
            (totalVolume / config.preFilterCapacity * config.preFilterCost +
                    totalVolume / config.roMembraneCapacity * config.roMembraneCost +
                    totalVolume / config.postCarbonCapacity * config.postCarbonCost)
    // Break-even point
    val breakEven = if (savings > 0) config.initialInvestment / savings else Double.POSITIVE_INFINITY
    // Plastic waste avoided
    val plasticsAvoidedKg = (totalVolume * config.bottleWeight) / (config.bottleSize * 1000.0)
    val bottleCount = totalVolume / config.bottleSize
    val formattedSavings = savings.toInt().asDynamic().toLocaleString("en-US")
    // Break-even point
    val breakEvenMonths = if (savings > 0) config.initialInvestment / savings else Double.POSITIVE_INFINITY
    val breakEvenPoint = if (breakEvenMonths.isFinite()) {
        val years = (breakEvenMonths / 12).toInt()
        val months = (breakEvenMonths % 12).toInt()

        when {
            years > 0 && months > 0 -> "${years}y ${months}m"
            years > 0 -> "${years}y"
            else -> "${months}m"
        }
    } else {
        "N/A"
    }

    return GainsData(
        filteredVolume = "${totalVolume.asDynamic().toFixed(2)}",
        bottleCount = "${bottleCount.asDynamic().toFixed(0)}",
        plasticsAvoided = "${plasticsAvoidedKg.asDynamic().toFixed(2)}",
        financialGain = formattedSavings,
        breakEvenPoint = breakEvenPoint
    )
}

