@Composable
fun ChartsPage(repository: FirebaseAndIndexedDBRepository) {
    var showDeleteDialog by remember { mutableStateOf(false) }
    var messageToDelete by remember { mutableStateOf<AppNotification?>(null) }
    val accountHere by accountState.collectAsState()
    val scope = rememberCoroutineScope()
    val uploading by isUploadingMedia.collectAsState()
    val rawMessages by notifications.collectAsState()
    val messages = remember(rawMessages) {
        rawMessages.filter { it.id >= 10 }
    }
    LaunchedEffect(accountHere?.productId) {
        val account = accountHere ?: return@LaunchedEffect
        repository.markIncomingMessages(account, true, isAdmin = false, notifications = messages)
    }
    Div(
        attrs = {
            style {
                property("width", "100%")
                property("height", "100%")
                property("display", "flex")
                property("flex-direction", "column")
                property("background-color", "#FFFFFF")
                property("overflow", "hidden")
                boxSizing("border-box")
            }
        }
    ) {
        // ================= TOP =================
        Div(
            attrs = {
                style {
                    property("flex", "1")
                    property("min-height", "0")
                    property("overflow-y", "auto")
                    property("padding", "6px")
                    property("display", "flex")
                    property("flex-direction", "column")
                    property("gap", "10px")
                    property("background-color", "#FFFFFF")
                    boxSizing("border-box")
                }
            }
        ) {
            MessagesArea(
                messages = messages.sortedBy { it.timestamp },
                repository = repository,
                onDelete = { msg ->
                    messageToDelete = msg
                    showDeleteDialog = true
                },
                accountHere = accountHere
            )
        }

        // ================= BOTTOM =================
        Div(
            attrs = {
                style {
                    property("flex-shrink", "0")
                    property("height", "60px")
                    property("background-color", "white")
                    property("border-top", "1px solid #E0E0E0")
                    property("width", "100%")
                    display(DisplayStyle.Flex)
                    alignItems(AlignItems.Center)
                }
            }
        ) {
            ChatInputBar(
                uploading = uploading,
                // ================= TEXT =================
                onSendText = { text ->
                    scope.launch {
                        setUploading(true)
                        val timeSec = Clock.System.now().toEpochMilliseconds()
                        val nextId = if (messages.isEmpty()) {
                            10
                        } else {
                            val candidate = (messages.maxOf { it.id }) + 1
                            if (candidate < 10) 10 else candidate
                        }

                        val msg = AppNotification(
                            id = nextId,
                            accountId = (accountHere?.productId ?: 0),
                            title = "User",
                            message = text,
                            messageType = 0, // text
                            isread = false,
                            messageSender = 1,
                            timestamp = timeSec,
                            uploaded = true,
                            shouldTranslate = false
                        )

                        val account = accountHere ?: run {
                            setUploading(false)
                            return@launch
                        }
                        // ✅ Call the unified helper with initialUploaded = true
                        finalizeNotificationSend(
                            repository = repository,
                            account = account,
                            notification = msg,
                            messages = messages,
                            initialUploaded = true
                        )
                        setUploading(false)
                    }
                },

                onPickImage = {
                    pickImage { blob ->
                        blob ?: run {
                            println("[IMAGE] No blob returned from picker, aborting.")
                            return@pickImage
                        }
                        scope.launch {
                            println("[IMAGE] Starting image upload flow…")
                            setUploading(true)

                            val timeSec = Clock.System.now().toEpochMilliseconds()
                            val key = "img_${timeSec}"
                            val nextId = if (messages.isEmpty()) 10 else {
                                val candidate = (messages.maxOf { it.id }) + 1
                                if (candidate < 10) 10 else candidate
                            }
                            println("[IMAGE] Generated key=$key, nextId=$nextId")

                            var msg = AppNotification(
                                id = nextId,
                                accountId = (accountHere?.productId ?: 0),
                                title = "User",
                                message = key,
                                messageType = 1, // image
                                isread = false,
                                messageSender = 1,
                                timestamp = timeSec,
                                uploaded = true,
                                shouldTranslate = false
                            )
                            println("[IMAGE] Built AppNotification id=${msg.id}, uploaded=${msg.uploaded}")
                            // ✅ Save media blob locally right away
                            repository.saveMedia(
                                mediaKey = key,
                                blob = blob,
                                type = 1 // image
                            )
                            println("[IMAGE] Saved blob locally with key=$key")
                            val account = accountHere
                            if (account == null) {
                                println("[IMAGE] No account available, saving offline as uploaded=false")
                                val failed = msg.copy(uploaded = false)
                                repository.saveOrUpdateOfflineNotification(failed)
                                addOrUpdateNotificationFromPhone(failed)
                                setUploading(false)
                                return@launch
                            }

                            println("[IMAGE] Uploading blob to cloud with key=$key")

                            val uploadOk = repository.uploadMediaToCloud(
                                key = key,
                                blob = blob,
                                mimeType = "image/*"
                            )
                            println("[IMAGE] Cloud upload result: $uploadOk")
                            // ✅ Call unified helper with upload result
                            val finalMsg = finalizeNotificationSend(
                                repository = repository,
                                account = account,
                                notification = msg,
                                messages = messages,
                                initialUploaded = uploadOk
                            )
                            println("[IMAGE] Final message status id=${finalMsg.id}, uploaded=${finalMsg.uploaded}")

                            setUploading(false)
                            println("[IMAGE] Image upload flow finished.")
                        }
                    }
                },
                        // ================= AUDIO =================
                onRecordAudio = {
                    pickAudio { blob ->
                        blob ?: return@pickAudio
                        scope.launch {
                            setUploading(true)
                            val timeSec = Clock.System.now().toEpochMilliseconds()
                            val key = "audio_${timeSec}"
                            val nextId = if (messages.isEmpty()) 10 else {
                                val candidate = (messages.maxOf { it.id }) + 1
                                if (candidate < 10) 10 else candidate
                            }

                            val msg = AppNotification(
                                id = nextId,
                                accountId = (accountHere?.productId ?: 0),
                                title = "User",
                                message = key,
                                messageType = 4, // audio
                                isread = false,
                                messageSender = 1,
                                timestamp = timeSec,
                                uploaded = true,
                                shouldTranslate = false
                            )
                            val account = accountHere
                            if (account == null) {
                                val failed = msg.copy(uploaded = false)
                                repository.saveOrUpdateOfflineNotification(failed)
                                addOrUpdateNotificationFromPhone(failed)
                                setUploading(false)
                                return@launch
                            }
                            val uploadOk = repository.uploadMediaToCloud(
                                key = key,
                                blob = blob,
                                mimeType = "audio/*"
                            )
                            // ✅ Call unified helper with upload result
                            finalizeNotificationSend(
                                repository = repository,
                                account = account,
                                notification = msg,
                                messages = messages,
                                initialUploaded = uploadOk
                            )

                            setUploading(false)
                        }
                    }
                },
                // ================= VIDEO =================
                // ================= VIDEO =================
                onRecordVideo = {
                    pickVideo { blob ->
                        blob ?: return@pickVideo
                        scope.launch {
                            setUploading(true)
                            val timeSec = Clock.System.now().toEpochMilliseconds()
                            val key = "video_${timeSec}"
                            val nextId = if (messages.isEmpty()) 10 else {
                                val candidate = (messages.maxOf { it.id }) + 1
                                if (candidate < 10) 10 else candidate
                            }

                            val msg = AppNotification(
                                id = nextId,
                                accountId = (accountHere?.productId ?: 0),
                                title = "User",
                                message = key,
                                messageType = 3, // video
                                isread = false,
                                messageSender = 1,
                                timestamp = timeSec,
                                uploaded = true,
                                shouldTranslate = false
                            )

                            val account = accountHere
                            if (account == null) {
                                val failed = msg.copy(uploaded = false)
                                repository.saveOrUpdateOfflineNotification(failed)
                                addOrUpdateNotificationFromPhone(failed)
                                setUploading(false)
                                return@launch
                            }

                            val uploadOk = repository.uploadMediaToCloud(
                                key = key,
                                blob = blob,
                                mimeType = "video/*"
                            )
                            // ✅ Call unified helper with upload result
                            finalizeNotificationSend(
                                repository = repository,
                                account = account,
                                notification = msg,
                                messages = messages,
                                initialUploaded = uploadOk
                            )

                            setUploading(false)
                        }
                    }
                }
            )
        }
    }

    if (showDeleteDialog && messageToDelete != null) {
        DeleteConfirmDialog(
            isRestore = messageToDelete!!.title == "deleted",
            isDeleting = false,
            onDismiss = {
                showDeleteDialog = false
                messageToDelete = null
            },
            onCancel = {
                showDeleteDialog = false
                messageToDelete = null
            },
            onConfirm = {
                val msg = messageToDelete ?: return@DeleteConfirmDialog
                scope.launch {
                    val deletedMsg = msg.copy(
                        title = if (messageToDelete!!.title == "deleted") "restored" else "deleted"
                    )
                    val account = accountHere ?: return@launch
                    repository.saveOrUpdateOfflineNotification(deletedMsg)
                    addOrUpdateNotificationFromPhone(deletedMsg)
                    finalizeNotificationSend(
                        repository = repository,
                        account = account,
                        notification = deletedMsg,
                        messages = messages,
                        initialUploaded = true
                    )
                    showDeleteDialog = false
                    messageToDelete = null
                }
            }
        )
    }
}

@NoLiveLiterals
suspend fun finalizeNotificationSend(
    repository: FirebaseAndIndexedDBRepository,
    account: AccountEntity,
    notification: AppNotification,
    messages: List<AppNotification>,
    initialUploaded: Boolean,
    isAdmin: Boolean = false
): AppNotification {
    val timeSec = Clock.System.now().toEpochMilliseconds()
    var msg = notification.copy(uploaded = initialUploaded)
    if(!isAdmin) addOrUpdateNotificationFromPhone(msg)
    val rtdbOk = repository.saveMessageToRTDB(account.decryptedProductId, msg)
    var adminOk = true
    if(!isAdmin) {
        val unreadUserMessages = messages.filter { it.messageSender == 1 && !it.isread }
        val count = unreadUserMessages.size
        adminOk = repository.informAdminOfMessage(
            productId = account.decryptedProductId,
            lastMessage = msg.copy(timestamp = timeSec),
            messageCount = count
        )
    }
    // If either failed, mark uploaded=false
    if (!rtdbOk || !adminOk) {
        msg = msg.copy(uploaded = false)
    }
    // Persist offline
    if(!isAdmin) {
        repository.saveOrUpdateOfflineNotification(msg)
        addOrUpdateNotificationFromPhone(msg)
    }
    return msg
}

fun pickImage(onResult: (Blob?) -> Unit) {
    val input = document.createElement("input") as HTMLInputElement
    input.type = "file"
    input.accept = "image/*"

    input.onchange = {
