@Composable
fun MessageHeader(
    message: AppNotification,
    sender: String,
    alignRight: Boolean,
    onDelete: (AppNotification) -> Unit,
    onRestore: (AppNotification) -> Unit,
    isAdmin:Boolean = false
) {
    val instant = Instant.fromEpochMilliseconds(message.timestamp)
    val localDT = instant.toLocalDateTime(TimeZone.currentSystemDefault())
    val formatted =
        "${localDT.dayOfMonth}/${localDT.monthNumber}/${localDT.year} " +
                "${localDT.hour}:${localDT.minute.toString().padStart(2, '0')}"
    val isDeleted = message.title == "deleted"
    Div({
        style {
            property("width", "100%")
            property("display", "flex")
            property(
                "justify-content",
                if (alignRight) "flex-end" else "flex-start"
            )
            property("font-size", "12px")
            property("color", "#666")
            property("gap", "6px")
            property("align-items", "center")
        }
    }) {

        // LEFT: sender + time
        Text("$sender • $formatted")

        // STATUS ICONS (UNCHANGED)
        if ((message.messageSender == 1 && !isAdmin) || (message.messageSender == 0 && isAdmin)) {
            when {
                !message.uploaded -> Text("❌")
                message.uploaded && message.isread -> {
                    Div({ style { property("color", "#0000FF") } }) {
                        Text("✓✓")
                    }
                }
                message.uploaded && message.shouldTranslate -> {
                    Div({ style { property("color", "#888") } }) {
                        Text("✓✓")
                    }
                }
                message.uploaded -> {
                    Div({ style { property("color", "#888") } }) {
                        Text("✓")
                    }
                }
            }
        }
        if ((message.messageSender == 1 && !isAdmin) || (message.messageSender == 0 && isAdmin)) {
            Div({
                style {
                    property("cursor", "pointer")
                    property("display", "flex")
                    property("align-items", "center")
                }
                onClick {
                    if (isDeleted) {
                        onRestore(message)
                    } else {
                        onDelete(message)
                    }
                }
            }) {
                IconForPanel(if (isDeleted) "restore" else "delete", 16, altText = if (isDeleted) "restore" else "delete", tint = "#000000")
            }
        }
    }
}

@Composable
fun MessageContent(
    message: AppNotification,
    repository: FirebaseAndIndexedDBRepository
) {
    if (message.title == "deleted") {
        Div({
            style {
                color(Color("#888"))
                fontStyle("italic")
            }
        }) {
            Text("this message was deleted")
        }
        return
    }
    when (message.messageType) {
        0 -> Text(message.message)
        1 -> ImageMessage(message, repository)
        4 -> AudioMessage(message, repository)
        3 -> VideoMessage(message, repository)
    }
}


