                field = "Address",
                value = updatedAccount.address,
                onEdit = {
                    editField = "address"
                    editValue = updatedAccount.address
                    showEditDialog = true
                }
            )
            SettingsDivider()

            // WIFI NAME (selector dialog)
            SettingsItem(
                field = "WiFi Name",
                value = updatedAccount.wifiName,
                onEdit = { showWifiDialog = true }
            )
            SettingsDivider()
            // WIFI PASSWORD
            SettingsItem(
                field = "WiFi Password",
                value = "••••••",
                onEdit = {
                    editField = "wifi_password"
                    editValue = updatedAccount.wifiPass
                    showEditDialog = true
                }
            )
            SettingsDivider()
            // GPS LOCATION (NEW DIALOG)
            SettingsItem(
                field = "Location",
                value = if (updatedAccount.latitude.isNotEmpty() && updatedAccount.longitude.isNotEmpty()) {
                    "${updatedAccount.latitude}, ${updatedAccount.longitude}"
                } else {
                    "No location set"
