    // ================= WIFI =================
    if (showWifiDialog) {
        ShowWifiSelectorDialog(
            wifiNames = emptyList(),
            oldWifiName = updatedAccount.wifiName,
            isScanning = false,
            showManualEntry = true,
            onWifiSelected = {
                updatedAccount = updatedAccount.copy(wifiName = it)
                showWifiDialog = false
            },
            onDismiss = { showWifiDialog = false }
        )
