    // ================= GPS DIALOG (NEW SIMPLE INLINE) =================
    if (showGpsDialog && latitude != null && longitude != null) {
        Div({
            style {
                position(Position.Fixed)
                top(0.px)
                left(0.px)
                width(100.percent)
                height(100.percent)
                backgroundColor(Color("rgba(0,0,0,0.3)"))
                display(DisplayStyle.Flex)
                justifyContent(JustifyContent.Center)
                alignItems(AlignItems.Center)
            }
            onClick { showGpsDialog = false }
        }) {
            Div({
                onClick { it.stopPropagation() }
                style {
                    backgroundColor(Color(AppFrontGround))
                    padding(16.px)
                    borderRadius(10.px)
                    display(DisplayStyle.Flex)
                    flexDirection(FlexDirection.Column)
                    gap(12.px)
                    minWidth(320.px)
                }
            }) {
                H3({ style { textAlign("center") } }) {
                    Text("Confirm GPS Location")
                }

                // Map preview
                Iframe({
                    attr("src", "https://maps.google.com/maps?q=$latitude,$longitude&z=15&output=embed")
                    attr("width", "300")
                    attr("height", "200")
                    style {
                        borderRadius(8.px)
                        border(0.px)
                    }
                })
                Button(attrs = {
                    onClick {
                        updatedAccount = updatedAccount.copy(
                            latitude = latitude.toString(),
                            longitude = longitude.toString()
                        )
                        showGpsDialog = false
                    }
                }) {
                    Text("Accept")
                }
                Button(attrs = {
                    onClick { showGpsDialog = false }
                }) {
                    Text("Cancel")
                }
            }
        }
    }

    if (showConfirmPasswordDialog) {
        PasswordInputDialog(
            password = passwordForReauth,
            onPasswordChange = { passwordForReauth = it },
            promptLabel = I18n.t("password"),
            onDismiss = { showConfirmPasswordDialog = false },
            onConfirm = {
                val auth = getAuth()
                val currentUser = auth.currentUser
                if (currentUser == null || currentUser.email.isNullOrEmpty()) {
                    feedbackMessage = I18n.t("user_not_logged_in")
                    showConfirmPasswordDialog = false
                    return@PasswordInputDialog
                }

                coroutineScope.launch {
                    try {
                        val auth = getAuth()
                        val currentUser = auth.currentUser
                        if (currentUser == null || currentUser.email.isNullOrEmpty()) {
                            feedbackMessage = I18n.t("user_not_logged_in")
                            showConfirmPasswordDialog = false
                            return@launch
                        }
                        // 🔐 1. REAUTH (KEEP YOUR ORIGINAL METHOD)
                        signInWithEmailAndPassword(
                            auth,
                            currentUser.email!!,
                            passwordForReauth
                        ).await()
                        // 🔐 2. UPDATE PASSWORD (JS STYLE SAFE)
                        if (newPassword.isNotBlank()) {
                            currentUser.asDynamic().updatePassword(newPassword).await()
                            feedbackMessage = I18n.t("password_update_success")
                        }
                        // 💾 3. SAVE DB CHANGES
                        onSave(updatedAccount, updatedUser)
                        if (newPassword.isBlank()) {
                            feedbackMessage = I18n.t("name_update_success")
                        }

                    } catch (e: dynamic) {
                        feedbackMessage = I18n.t("incorrect_password")
                    } finally {
                        showConfirmPasswordDialog = false
                        passwordForReauth = ""
                    }
                }
            },
            isPasswordVisible = isPasswordVisible,
            onToggleVisibility = { isPasswordVisible = !isPasswordVisible }
        )
    }

}

