fun getCurrentDateFormatted(locale: String = "en-US"): String {
    val now = js("new Date()") as Date
    val year = now.getFullYear()
    val month = (now.getMonth() + 1)
    val day = now.getDate()

    fun toLocaleDigits(number: Int): String {
        return number.asDynamic().toLocaleString(locale).unsafeCast<String>().padStart(2, '0')
    }

    return "${toLocaleDigits(year)}-${toLocaleDigits(month)}-${toLocaleDigits(day)}"
}

@Composable
fun AccountSwitchDialog(
    currentUser: UserEntity?,
    onUserSwitched: (UserEntity?, Boolean) -> Unit,
    showDialog: Boolean,
    onDismiss: () -> Unit
) {
    val user = currentUser ?: return
    var hoveredProduct by remember { mutableStateOf<String?>(null) }

    if (showDialog) {
        // Overlay
        Div({
            style {
                position(Position.Fixed)
                top(0.px)
                left(0.px)
                width(100.percent)
                height(100.percent)
                backgroundColor(Color("rgba(0,0,0,0.5)"))
                display(DisplayStyle.Flex)
                justifyContent(JustifyContent.Center)
                alignItems(AlignItems.Center)
            }
            onClick {
                onUserSwitched(user, false)
                onDismiss()
            }
        }) {
            // Dialog box
            Div({
                style {
                    backgroundColor(Color(AppFrontGround))
                    borderRadius(16.px)
                    padding(16.px)
                    width(80.percent)
                    maxWidth(600.px)
                    maxHeight(400.px)
                    overflowY("auto")
                }
                onClick { /* stop propagation */ }
            }) {
                // Title
                H3({
                    style {
                        textAlign("center")
                        color(Color(actionColor))
                        fontSize(20.px)
                        fontWeight("bold")
                        marginBottom(16.px)
                    }
                }) { Text(I18n.t("account_switch_title")) }

                // Options
                val productOptions = user.ownedProducts.filter { it != user.loggedIntoProduct }
                productOptions.forEach { productId ->
                    Div({
                        style {
                            width(100.percent)
                            paddingTop(4.px)
                            paddingBottom(4.px)
                            cursor("pointer")
                            backgroundColor(
                                if (hoveredProduct == productId) Color("#E0E0E0") else Color("transparent")
                            )
                        }
                        onMouseEnter { hoveredProduct = productId }
                        onMouseLeave { hoveredProduct = null }
                        onClick {
                            val updatedUser = user.copy(
                                loggedIntoProduct = productId,
                                lastLoginRole = "user",
                                lastAccessedDate = getCurrentDateFormatted()
                            )
                            onUserSwitched(updatedUser, true)
                            onDismiss()
                        }
                    }) {
                        P({
                            style {
                                fontSize(18.px)
                                color(Color(TextColor))
                                margin(0.px)
                            }
                        }) { Text(productId) }

                        Hr({
                            style {
                                marginTop(4.px)
                                marginBottom(4.px)
                                borderWidth(1.px)
                            }
                        })
                    }
                }

                // Close button
                Div({
                    style {
                        display(DisplayStyle.Flex)
                        justifyContent(JustifyContent.FlexEnd)
                        marginTop(16.px)
                    }
                }) {
                    Button({
                        style {
                            backgroundColor(Color(actionColor))
                            color(Color(AppFrontGround))
                            borderRadius(6.px)
                            padding(8.px, 14.px)
                            fontSize(14.px)
                            cursor("pointer")
                        }
                        onClick {
                            onUserSwitched(user, false)
                            onDismiss()
                        }
                    }) { Text(I18n.t("close")) }
                }
            }
        }
    }
}


