@Composable
fun ShowWifiSelectorDialog(
    wifiNames: List<String>,
    oldWifiName: String,
    isScanning: Boolean,
    showManualEntry: Boolean,
    onWifiSelected: (String) -> Unit,
    onDismiss: () -> Unit
) {
    var manualText by remember { mutableStateOf(oldWifiName) }
    // FULLSCREEN OVERLAY (like EditDialog)
    Div({
        style {
            position(Position.Fixed)
            top(0.px)
            left(0.px)
            width(100.percent)
            height(100.percent)
            backgroundColor(Color("rgba(0, 0, 0, 0.3)"))
            display(DisplayStyle.Flex)
            justifyContent(JustifyContent.Center)
            alignItems(AlignItems.Center)

            property("z-index", "9999")
        }

        onClick { onDismiss() }
    }) {

        // DIALOG CARD
        Div({
            onClick { it.stopPropagation() }

            style {
                display(DisplayStyle.Flex)
                flexDirection(FlexDirection.Column)
                gap(10.px)
                property("width", "auto")
                minWidth(260.px)
                maxWidth(500.px)
                backgroundColor(Color(AppFrontGround))
                color(Color(TextColor))
                borderRadius(10.px)
                padding(16.px)
                boxSizing("border-box")
            }
        }) {

            // TITLE
            H3({
                style {
                    textAlign("center")
                    fontSize(16.px)
                    margin(0.px)
                    color(Color(actionColor))
                }
            }) {
                Text(I18n.t("wifi_selector_title"))
            }

            // ================= MANUAL MODE =================
            if (showManualEntry) {

                Input(InputType.Text) {
                    value(manualText)
                    placeholder(I18n.t("wifi_name"))

                    onInput { ev ->
                        manualText = ev.value
                    }

                    style {
                        width(90.percent)
                        padding(8.px)
                    }
                }

                Div({
                    style {
                        display(DisplayStyle.Flex)
                        justifyContent(JustifyContent.SpaceBetween)
                        marginTop(10.px)
                    }
                }) {

                    Button(attrs = {
                        onClick { onDismiss() }
                    }) {
                        Text(I18n.t("close"))
                    }

                    Button(attrs = {
                        onClick {
                            onWifiSelected(manualText)
                        }
                        style {
                            backgroundColor(Color(actionColor))
                            color(Color(AppFrontGround))
                            padding(6.px, 12.px)
                            borderRadius(6.px)
                        }
                    }) {
                        Text(I18n.t("ok"))
                    }
                }
            }
            // ================= SCAN MODE =================
            else {
                when {
                    isScanning -> {
                        P({ style { textAlign("center") } }) {
                            Text(I18n.t("scanning..."))
                        }
                    }
                    wifiNames.isEmpty() -> {
                        P({
                            style {
                                textAlign("center")
                                color(Color("#808080"))
                            }
                        }) {
                            Text(I18n.t("no_wifi_found"))
                        }
                    }

                    else -> {
                        Div({
                            style {
                                maxHeight(300.px)
                                overflowY("auto")
                            }
                        }) {

                            wifiNames.forEach { ssid ->

                                Button(attrs = {
                                    onClick {
                                        onWifiSelected(ssid)
                                    }
                                    style {
                                        width(90.percent)
                                        marginTop(4.px)
                                        padding(8.px)
                                        backgroundColor(Color(AppFrontGround))
                                        color(Color(TextColor))
                                        borderRadius(6.px)
                                    }
                                }) {
                                    Text(ssid)
                                }
                            }
                        }
                    }
                }
                // CLOSE BUTTON
                Button(attrs = {
                    onClick { onDismiss() }
                    style {
                        marginTop(12.px)
                        padding(8.px, 16.px)
                    }
                }) {
                    Text(I18n.t("close"))
                }
            }
        }
    }
}

