fun setAdminProductNotifications(productId: String, notifs: List<AppNotification>, repository: FirebaseAndIndexedDBRepository) {
    val current = _adminNotificationsByProduct.value.toMutableMap()
    current[productId] = notifs
    _adminNotificationsByProduct.value = current

    // 🔑 Immediately mark incoming messages for this product
    val account = adminAccountsByProduct.value[productId]
    if (account != null) {
        CoroutineScope(Dispatchers.Default).launch {
            repository.markIncomingMessages(
                account = account,
                markRead = false,   // do not mark as read
                isAdmin = true,     // admin side
                notifications = notifs
            )
        }
    }
}

