@NoLiveLiterals
fun loadNotifications(
    account: AccountEntity,
    repository: FirebaseAndIndexedDBRepository
) {
    val db = getDatabase()
    val notificationsRef =
        ref(db, "products/${account.decryptedProductId}/notifications")
    onValue(notificationsRef) { snapshot ->
        _isLoading.value = true
        if (!snapshot.exists()) {
            _isLoading.value = false
            return@onValue
        }
        get(notificationsRef).then { fullSnapshot ->
            val fetchedNotifications = mutableListOf<AppNotification>()
            val rootData = fullSnapshot.`val`() ?: run {
                _isLoading.value = false
                return@then
            }
            val keys = js("Object.keys(rootData)") as Array<String>
            for (key in keys) {
                val notif = rootData.asDynamic()[key]
                val parsed = AppNotification(
                    id = (notif.id as? Number)?.toInt() ?: 0,
                    accountId = (notif.accountId as? Number)?.toInt()
                        ?: account.productId,
                    title = notif.title as? String ?: "",
                    message = notif.message as? String ?: "",
                    messageType = (notif.messageType as? Number)?.toInt() ?: 0,
                    isread = notif.isread as? Boolean ?: false,
                    messageSender = (notif.messageSender as? Number)?.toInt() ?: 0,
                    timestamp = (notif.timestamp as? Number)?.toLong() ?: 0L,
                    uploaded = notif.uploaded as? Boolean ?: false,
                    shouldTranslate = notif.shouldTranslate as? Boolean ?: true
                )
                fetchedNotifications.add(parsed)
            }
            val sortedUpdated =
                fetchedNotifications.sortedByDescending { it.timestamp }
            val currentNotifications = _notifications.value
            CoroutineScope(Dispatchers.Default).launch {
                sortedUpdated.forEach { incoming ->
                    val existing = currentNotifications.firstOrNull {
                        it.id == incoming.id &&
                                it.timestamp == incoming.timestamp
                    }
                    if (existing == null || existing != incoming) {
                        //repository.saveOrUpdateOfflineNotification(incoming)
                    }
                }
                repository.markIncomingMessages(
                    account = account,
                    markRead = false,
                    isAdmin = false,
                    notifications = sortedUpdated
                )
            }

            setOfflineErrors(sortedUpdated)
            _notifications.value = sortedUpdated
            _hasNewNotification.value = true
            _isLoading.value = false

        }.catch {
            _isLoading.value = false
        }
    }
}

@NoLiveLiterals
fun loadAdminConfig(
    account: AccountEntity,
    repository: FirebaseAndIndexedDBRepository
) {
    val db = getDatabase()
    val configRef = ref(db, "admin/config")

    onValue(configRef) { snapshot ->
        _isLoading.value = true

        if (!snapshot.exists()) {
            console.log("No AdminConfig found in Firebase for ${account.decryptedProductId}")
            _isLoading.value = false
            return@onValue
        }

        get(configRef).then { fullSnapshot ->
            val obj = fullSnapshot.`val`() ?: run {
                _isLoading.value = false
                return@then
            }

            val newConfig = AdminConfig(
                initialInvestment   = (obj.asDynamic()["initialInvestment"]   as? Number)?.toDouble() ?: 0.0,
                bottledWaterCost    = (obj.asDynamic()["bottledWaterCost"]    as? Number)?.toDouble() ?: 0.0,
                preFilterCapacity   = (obj.asDynamic()["preFilterCapacity"]   as? Number)?.toDouble() ?: 0.0,
                preFilterCost       = (obj.asDynamic()["preFilterCost"]       as? Number)?.toDouble() ?: 0.0,
                roMembraneCapacity  = (obj.asDynamic()["roMembraneCapacity"]  as? Number)?.toDouble() ?: 0.0,
                roMembraneCost      = (obj.asDynamic()["roMembraneCost"]      as? Number)?.toDouble() ?: 0.0,
                postCarbonCapacity  = (obj.asDynamic()["postCarbonCapacity"]  as? Number)?.toDouble() ?: 0.0,
                postCarbonCost      = (obj.asDynamic()["postCarbonCost"]      as? Number)?.toDouble() ?: 0.0,
                bottleSize          = (obj.asDynamic()["bottleSize"]          as? Number)?.toDouble() ?: 0.0,
                bottleWeight        = (obj.asDynamic()["bottleWeight"]        as? Number)?.toDouble() ?: 0.0
            )

            CoroutineScope(Dispatchers.Default).launch {
                val offlineConfig = repository.getOfflineAdminConfig()

                // 🔑 Guard: skip saving if everything is zero
                val isEmptyConfig = newConfig == AdminConfig(
                    initialInvestment = 0.0,
                    bottledWaterCost = 0.0,
                    preFilterCapacity = 0.0,
                    preFilterCost = 0.0,
                    roMembraneCapacity = 0.0,
                    roMembraneCost = 0.0,
                    postCarbonCapacity = 0.0,
                    postCarbonCost = 0.0,
                    bottleSize = 0.0,
                    bottleWeight = 0.0
                )

                if (isEmptyConfig) {
                    console.warn("AdminConfig stream returned empty values → skipping save")
                } else if (offlineConfig != newConfig) {
                    console.log("AdminConfig changed → saving offline")
                    repository.saveOrUpdateOfflineAdminConfig(newConfig)
                } else {
                    console.log("AdminConfig unchanged → no update needed")
                }
            }

            _isLoading.value = false
        }.catch {
            console.error("Error fetching AdminConfig from Firebase")
            _isLoading.value = false
        }
    }
}



@NoLiveLiterals
fun loadWaterResults(
    account: AccountEntity,
    repository: FirebaseAndIndexedDBRepository
) {
    val db = getDatabase()
    val liveRef = ref(db, "products/${account.decryptedProductId}/live")

    onValue(liveRef) { snapshot ->
        if (!snapshot.exists()) {
            return@onValue
        }

        val rootData = snapshot.`val`() ?: return@onValue

        val current = getWaterResult() ?: WaterResult()
        fun pickOne(node: dynamic): dynamic? {
            if (node == null) return null
            val keys = js("Object.keys(node)") as Array<String>
            return if (keys.isNotEmpty()) node[keys[0]] else null
        }

        val sensorNode = pickOne(rootData.asDynamic().SensorValue)
        val generalNode = pickOne(rootData.asDynamic().General)
        val statusNode  = pickOne(rootData.asDynamic().status) // lowercase in dump

        val updated = current.copy(
            // --- SensorValue ---
            turbidity   = (sensorNode?.Turbidity   as? Number)?.toFloat() ?: current.turbidity,
            ph          = (sensorNode?.PH          as? Number)?.toFloat() ?: current.ph,
            tds         = (sensorNode?.Tds         as? Number)?.toFloat() ?: current.tds,
            temperature = (sensorNode?.Temperature as? Number)?.toFloat() ?: current.temperature,
            volume      = (sensorNode?.Volume      as? Number)?.toFloat() ?: current.volume,
            time        = (sensorNode?.Time        as? Number)?.toLong()  ?: current.time,

            // --- General ---
            mineralDate   = generalNode?.MineralDate   as? String ?: current.mineralDate,
            mineralVolume = (generalNode?.MineralVolume as? Number)?.toFloat() ?: current.mineralVolume,
            mineralCount  = (generalNode?.MineralCount  as? Number)?.toInt() ?: current.mineralCount,
            preDate       = generalNode?.PreDate       as? String ?: current.preDate,
            preVolume     = (generalNode?.PreVolume    as? Number)?.toFloat() ?: current.preVolume,
            preCount      = (generalNode?.PreCount     as? Number)?.toInt() ?: current.preCount,
            reverseDate   = generalNode?.ReverseDate   as? String ?: current.reverseDate,
            reverseVolume = (generalNode?.ReverseVolume as? Number)?.toFloat() ?: current.reverseVolume,
            reverseCount  = (generalNode?.ReverseCount  as? Number)?.toInt() ?: current.reverseCount,
            totalVolume   = (generalNode?.TotalVolume   as? Number)?.toFloat() ?: current.totalVolume,

            // --- Status ---
            filter = statusNode?.Filter as? String ?: current.filter,
            sensor = statusNode?.Sensor as? String ?: current.sensor
        )
        setWaterResult(updated)
        _hasNewWaterResult.value = true
        if (statusNode != null) {
            handleStatusNotifications(account, repository, updated)
        }
    }
}

@NoLiveLiterals
fun addOrUpdateNotificationFromPhone(notification: AppNotification) {
    val current = _notifications.value.toMutableList()

    val existingIndex = current.indexOfFirst {
        if (notification.id < 10) {
            // For IDs < 10, match only by ID
            it.id == notification.id
        } else {
            // For all other IDs, match by both ID and timestamp
            it.id == notification.id && it.timestamp == notification.timestamp
        }
    }

    if (existingIndex != -1) {
        current[existingIndex] = notification
    } else {
        current.add(notification)
    }

    val updated = current.sortedByDescending { it.timestamp }
    _notifications.value = updated
    setOfflineErrors(updated)
    _hasNewNotification.value = true
}


fun setupPersistence(
    repository: FirebaseAndIndexedDBRepository,
    waterResult: StateFlow<WaterResult?>
) {
    // Save before page unload
    window.onbeforeunload = {
        val current = waterResult.value
        CoroutineScope(Dispatchers.Default).launch {
            if (current != null) {
                repository.saveOrUpdateOfflineWaterResult(current)
            }
        }
        null // ✅ return null instead of Job
    }

    // Save when network goes offline
    window.addEventListener("offline", {
        val current = waterResult.value
        CoroutineScope(Dispatchers.Default).launch {
            if (current != null) {
                repository.saveOrUpdateOfflineWaterResult(current)
            }
        }
    })
}


fun handleStatusNotifications(
    account: AccountEntity,
    repository: FirebaseAndIndexedDBRepository,
    result: WaterResult
) {
    val notifTime = result.time * 1000 // hardware epoch seconds → ms
    val filters = result.filter.split(",").map { it.trim() }

    val filterMap = mapOf(
        "Pre" to Pair(1, "Pre-Filter Change Alert"),
        "Reverse" to Pair(2, "Reverse Osmosis Alert"),
        "Mineral" to Pair(3, "Mineralization Alert")
    )

    val sensorMap = mapOf(
        "RTC NOT PRESENT" to Pair(4, "RTC Not Present"),
        "RTC BATTERY IS LOW" to Pair(5, "RTC Battery Low"),
        "TEMPERATURE SENSOR ERROR" to Pair(6, "Temperature Sensor Error"),
        "PH SENSOR ERROR" to Pair(7, "pH Sensor Error")
    )

    val allMappings = filterMap.map { Triple(it.value.first, it.value.second, filters.contains(it.key)) } +
            sensorMap.map { Triple(it.value.first, it.value.second, result.sensor.contains(it.key)) }

    allMappings.forEach { (id, title, active) ->
        val notif = AppNotification(
            id = id,
            accountId = account.productId,
            title = if (active) title else "deleted",
            message = title,
            messageType = if (active) 1 else 0,
            isread = false,
            messageSender = 0,
            timestamp = notifTime,
            uploaded = id > 3,
            shouldTranslate = true
        )
        // 🔑 Override logic
        val existing = _notifications.value.toMutableList()
        val index = if (id < 10) {
            existing.indexOfFirst { it.id == id }
        } else {
            existing.indexOfFirst { it.id == id && it.timestamp == notifTime }
        }
        if (index >= 0) {
            console.log("Overriding notification at index=$index with id=$id, time=$notifTime")
            existing[index] = notif
        } else {
            console.log("Adding new notification: id=$id, title=$title, time=$notifTime")
            existing.add(notif)
        }
        addOrUpdateNotificationFromPhone(notif)
        CoroutineScope(Dispatchers.Default).launch {
            repository.saveOrUpdateOfflineNotification(notif)
            _account.value?.let { repository.saveMessageToRTDB(it.decryptedProductId, notif) }
        }
        _notifications.value = existing
        _hasNewNotification.value = true
    }
}
